import {localityInput,resolvePlace,placeForAirport,airportName} from './localities.js?v=8';
import {sharedUi} from './app.js?v=8';
import {flightRequest,signedIn} from './cloud-v2.js?v=8';
import {esc,money} from './core.js?v=8';
const label=code=>placeForAirport(code)?.city||code;
const date=days=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);
let query={origin:'GRU',destination:'',depart:date(35),return:date(42),stops:'any'},result=null,error='',busy=false,sort='price',chosen=null;
const exactMoney=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const minute=n=>`${Math.floor(n/60)}h${n%60?` ${n%60}min`:''}`;
const time=s=>s?.slice(11,16)||'—';
const shortDate=s=>new Date(s.slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
function legSummary(f,i){const first=f.legs[0],last=f.legs.at(-1);return `<div class="flight-leg"><div class="leg-direction">${i?'VOLTA':'IDA'} <span>${esc(shortDate(first.departure))}</span></div><div class="leg-times"><strong>${esc(time(first.departure))}<small>${esc(first.origin)}</small></strong><div class="leg-path"><span>${minute(f.duration)}</span><i></i><span>${f.stops?`${f.stops} parada${f.stops>1?'s':''}`:'Direto'}</span></div><strong>${esc(time(last.arrival))}<small>${esc(last.dest)}${last.arrival.slice(0,10)!==first.departure.slice(0,10)?' · '+esc(shortDate(last.arrival)):''}</small></strong></div><div class="leg-airline">${esc(f.airlineName||first.airlineName)}</div><p class="airport-names">${esc(airportName(first.origin))} → ${esc(airportName(last.dest))}</p></div>`;}
function offerCard(o,index){return `<article class="offer-card"><div class="offer-flights">${o.flights.map(legSummary).join('')}<details><summary>Ver voos e conexões</summary><div class="offer-details">${o.flights.map((f,i)=>`<strong>${i?'Volta':'Ida'}</strong>${f.legs.map(l=>`<p>${esc(l.airlineName||l.airline)} · ${esc(l.airline)} ${esc(l.flightNumber)}<br>${esc(airportName(l.origin))} ${esc(shortDate(l.departure))} ${esc(time(l.departure))} → ${esc(airportName(l.dest))} ${esc(shortDate(l.arrival))} ${esc(time(l.arrival))}</p>`).join('')}`).join('')}<p>Horários locais de cada aeroporto. Classe econômica. Bagagem despachada não confirmada.</p></div></details></div><div class="offer-price">${index===0&&sort==='price'?'<span class="badge">MENOR DESTA CONSULTA</span>':''}<small>Ida e volta · 2 adultos</small><strong>${exactMoney(o.total)}</strong><span>${exactMoney(o.perPerson)} por pessoa</span><a class="btn primary" href="${esc(o.bookingUrl)}" target="_blank" rel="noopener noreferrer">Conferir preço ↗</a><button class="btn ghost" data-watch-offer="${esc(o.id)}">Criar ping</button><small>Preço e disponibilidade podem mudar.</small></div></article>`;}
function watchForm(){return '';}

let initialized=false;
function render(){if(!initialized){query.origin=sharedUi.state.settings.origin||sharedUi.state.pings[0]?.origin||'GRU';initialized=true;}const list=result?[...result.offers].sort((a,b)=>sort==='duration'?a.flights.reduce((s,f)=>s+f.duration,0)-b.flights.reduce((s,f)=>s+f.duration,0):a.total-b.total):[];return sharedUi.pageHeader('BORA FAZER AS MALAS','O próximo destino começa aqui.','Passagens de ida e volta para vocês dois. Preços em reais, sem assinatura.')+`<section class="panel search-panel"><form id="flight-search-form"><div class="flight-fields"><div class="field"><label for="flight-origin">De onde?</label>${localityInput('flight-origin','origin',query.origin,'Cidade de saída')}</div><button class="swap-airports" type="button" data-swap-airports aria-label="Inverter origem e destino">⇄</button><div class="field"><label for="flight-destination">Para onde vamos?</label>${localityInput('flight-destination','destination',query.destination,'Ex.: Lisboa')}</div><div class="field"><label for="flight-depart">Ida</label><input id="flight-depart" name="depart" type="date" value="${esc(query.depart)}" min="${date(0)}" max="${date(330)}" required></div><div class="field"><label for="flight-return">Volta</label><input id="flight-return" name="return" type="date" value="${esc(query.return)}" min="${esc(query.depart)}" max="${date(330)}" required></div></div><div class="search-options"><span class="traveler-chip">♧ 2 adultos · Econômica</span><div class="field"><label for="flight-stops">Conexões</label><select id="flight-stops" name="stops">${[['any','Todas as opções'],['direct','Somente diretos'],['one','Até 1 parada']].map(([v,t])=>`<option value="${v}" ${query.stops===v?'selected':''}>${t}</option>`).join('')}</select></div><button class="btn primary search-submit" type="submit" ${busy?'disabled':''}>${busy?'Consultando preços…':'Buscar passagens ↗'}</button></div></form></section><div id="flight-live" role="status" aria-live="polite">${busy?'<div class="search-loading"><span class="search-spinner"></span><h2>Procurando bons caminhos.</h2><p>Estamos combinando ida e volta. A consulta pode levar até um minuto.</p></div>':error?`<div class="hint search-error">${esc(error)} <br>Nenhum preço foi inventado. Seus radares continuam salvos.</div>`:''}</div>${watchForm()}${result&&!busy?`<div class="section-heading search-results-heading"><div><h2>${list.length?list.length+' opções para vocês':'Sem opções nesta consulta'}</h2><p>${esc(label(query.origin))} → ${esc(label(query.destination))} · Consultado em ${new Date(result.fetchedAt).toLocaleString('pt-BR')}${result.cached?' · resultado recente':''}</p></div><div class="field"><label for="flight-sort">Ordenar</label><select id="flight-sort"><option value="price" ${sort==='price'?'selected':''}>Menor preço</option><option value="duration" ${sort==='duration'?'selected':''}>Menor duração</option></select></div></div>${result.partial?'<div class="hint">Algumas opções não responderam. Exibindo os itinerários que foram confirmados nesta consulta.</div>':''}<section class="offers">${list.length?list.map(offerCard).join(''):'<div class="empty"><h2>Vamos tentar outras datas?</h2><p>Esta consulta não encontrou voos. Experimente outra cidade ou outras datas.</p></div>'}</section><p class="price-source">Fonte: Google Voos. Seleção entre os itinerários encontrados, sem garantia de cobrir todas as tarifas. O preço exibido inclui o valor retornado pela fonte; confirme taxas, franquia e disponibilidade antes de comprar. Bagagem despachada não confirmada. O AeroPing não vende passagens.</p>`:!busy&&!error?`<section class="search-welcome"><div class="search-orbit">✈</div><h2>O mundo cabe nos nossos planos.</h2><p>Escolha a cidade e as datas. Nós buscamos os preços; vocês escolhem a próxima aventura.</p><a href="#milhas" class="btn ghost">◇ Comparar dinheiro ou milhas</a></section>`:''}`;}
const redraw=()=>{if(location.hash==='#buscar')sharedUi.render();};
sharedUi.configure({search:render,openSearch(p){initialized=true;query={origin:p.origin,destination:p.destination,depart:p.depart,return:p.return,stops:p.stops};result=null;chosen=null;error='';location.hash='buscar';redraw();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['flight-search-form'].includes(form.id))return;e.preventDefault();if(!signedIn())return;const data=new FormData(form);try{
 if(form.id==='flight-search-form'){if(busy)return;const origin=resolvePlace(data.get('origin')),destination=resolvePlace(data.get('destination'));if(!origin||!destination)throw Error('Escolha uma cidade das sugestões.');query={origin:origin.code,destination:destination.code,depart:data.get('depart'),return:data.get('return'),stops:data.get('stops')};busy=true;error='';result=null;chosen=null;redraw();try{result=await flightRequest({query});}catch(e){error=e.name==='TimeoutError'?'A busca demorou mais que o esperado. Tente novamente.':e.message;}finally{busy=false;redraw();}}
 }catch(e){sharedUi.toast(e.message);}});
document.addEventListener('click',e=>{if(e.target.closest('[data-watch-offer]'))sharedUi.createPing(query);if(e.target.closest('[data-swap-airports]')){const a=document.querySelector('#flight-origin'),b=document.querySelector('#flight-destination');[a.value,b.value]=[b.value,a.value];}});

document.addEventListener('change',e=>{if(e.target.id==='flight-sort'){sort=e.target.value;redraw();}if(e.target.id==='flight-depart'){const r=document.querySelector('#flight-return');r.min=e.target.value;if(r.value<r.min)r.value=r.min;}});
